/**
 * Voiceover timing contract for the caffeine reel.
 *  - Each shot plays exactly one VO key; the assembler starts it at shot time VO_LEAD.
 *  - Shot duration = VO_LEAD + VO length + VO_TAIL (+ extra) → use shotDuration(key).
 *  - wordAt(key, "word") = shot-local seconds when that word starts (VO_LEAD included).
 * Regenerate VO with: python -I -X utf8 scripts/tts_caffeine.py --force
 */ 









const VO_LEAD = 0.4;
const VO_TAIL = 0.5;
const VO_WORDS = {
    hook: hook_namespaceObject,
    adeno: adeno_namespaceObject,
    caff: caff_namespaceObject,
    energy: energy_namespaceObject,
    time: caffeine_time_namespaceObject,
    crash: crash_namespaceObject,
    memory: memory_namespaceObject,
    tolerance: tolerance_namespaceObject,
    tips: tips_namespaceObject
};
const voLength = (key)=>vo_lengths_namespaceObject[key];
const shotDuration = (key, extra = 0)=>+(VO_LEAD + voLength(key) + VO_TAIL + extra).toFixed(2);
/** Shot-local time (s) when the n-th occurrence (0-based) of `word` starts. Prefix match allowed. */ const wordAt = (key, word, nth = 0)=>{
    const hits = VO_WORDS[key].filter((w)=>w.text === word || w.text.startsWith(word));
    const w = hits[Math.min(nth, hits.length - 1)];
    if (!w) throw new Error(`wordAt: "${word}" not in VO "${key}"`);
    return VO_LEAD + w.startMs / 1000;
};
/** Shot-local time (s) when that word finishes. */ const wordEnd = (key, word, nth = 0)=>{
    const hits = VO_WORDS[key].filter((w)=>w.text === word || w.text.startsWith(word));
    const w = hits[Math.min(nth, hits.length - 1)];
    if (!w) throw new Error(`wordEnd: "${word}" not in VO "${key}"`);
    return VO_LEAD + w.endMs / 1000;
};

